import { CommonModule } from '@angular/common';
import { Component, Input } from '@angular/core';
import { ObjectUtils, ValueExtractor } from 'espd-common/utils';
import { ColumnDefinition, RowItem } from '../table.model';

@Component({
	selector: 'espd-table-cell',
	templateUrl: './table-cell.component.html',
	styleUrls: ['./table-cell.component.scss'],
	imports: [CommonModule]
})
export class TableCellComponent {

	@Input()
	public item?: RowItem;

	@Input()
	public column?: ColumnDefinition;

	public extractValue(extractor: ValueExtractor): string {
		if (this.item) {
			return ObjectUtils.extractValue(this.item, extractor)?.toString() || '';
		} else {
			return '';
		}
	}
}